CREATE TABLE ibexa_node_assignment (id SERIAL NOT NULL, contentobject_id INT DEFAULT NULL, contentobject_version INT DEFAULT NULL, from_node_id INT DEFAULT 0, is_main INT DEFAULT 0 NOT NULL, op_code INT DEFAULT 0 NOT NULL, parent_node INT DEFAULT NULL, parent_remote_id VARCHAR(100) DEFAULT '' NOT NULL, remote_id VARCHAR(100) DEFAULT '0' NOT NULL, sort_field INT DEFAULT 1, sort_order INT DEFAULT 1, priority INT DEFAULT 0 NOT NULL, is_hidden INT DEFAULT 0 NOT NULL, PRIMARY KEY(id));
